CREATE OR REPLACE FUNCTION public.answer_appeal(p_appeal uuid, p_accept boolean, p_response text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  a public.community_appeals%rowtype;
  v_banned_by uuid;
  v_is_pro boolean;
begin
  select * into a from public.community_appeals where id = p_appeal;

  if not found then
    raise exception 'not_found';
  end if;

  if a.status <> 'pending' then
    raise exception 'already_handled';
  end if;

  v_is_pro := public.has_role(auth.uid(), 'pro'::public.app_role);

  if a.group_id is null then
    if not v_is_pro then
      raise exception 'not_allowed';
    end if;
  else
    select banned_by into v_banned_by
    from public.feed_group_bans
    where group_id = a.group_id and user_id = a.user_id;

    if not (
      v_is_pro
      or (
        public.is_group_owner(auth.uid(), a.group_id)
        and not coalesce(public.has_role(v_banned_by, 'pro'::public.app_role), false)
      )
    ) then
      raise exception 'not_allowed';
    end if;
  end if;

  if p_accept then
    if a.group_id is null then
      perform public.unban_community_member(a.user_id);
    else
      perform public.unban_group_member(a.group_id, a.user_id);
    end if;
  end if;

  update public.community_appeals
  set status = case when p_accept then 'accepted' else 'refused' end,
      response = nullif(btrim(left(p_response, 1000)), ''),
      handled_by = auth.uid(),
      handled_at = now()
  where id = p_appeal;

  if (not p_accept) or coalesce(btrim(p_response), '') <> '' then
    perform public.notify_user(
      a.user_id, 'moderation',
      case when p_accept then 'Votre demande a été acceptée' else 'Votre demande a été refusée' end,
      case when p_accept then 'Votre demande de réintégration a été acceptée.' else 'Votre demande de réintégration a été refusée.' end
        || case when coalesce(btrim(p_response), '') <> '' then ' Réponse : ' || left(btrim(p_response), 300) else '' end,
      '/groups'
    );
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.ban_group_member(p_group uuid, p_user uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_name text;
begin
  if not (public.is_group_owner(auth.uid(), p_group) or public.has_role(auth.uid(), 'pro'::public.app_role)) then
    raise exception 'not_allowed';
  end if;

  if public.has_role(p_user, 'pro'::public.app_role) or public.is_group_owner(p_user, p_group) then
    raise exception 'cannot_ban';
  end if;

  insert into public.feed_group_bans (group_id, user_id, reason, banned_by)
  values (p_group, p_user, left(p_reason, 300), auth.uid())
  on conflict (group_id, user_id) do update
    set reason = excluded.reason, banned_by = excluded.banned_by, created_at = now();

  update public.feed_group_members
  set status = 'banned', role = 'member'
  where group_id = p_group and user_id = p_user;

  select name into v_name from public.feed_groups where id = p_group;

  perform public.notify_user(
    p_user, 'moderation', 'Vous avez été banni(e) d''un groupe',
    'Vous avez été banni(e) du groupe « ' || coalesce(v_name, '') || ' » car une règle de la charte de respect n''a pas été respectée.'
      || case when coalesce(btrim(p_reason), '') <> '' then ' Motif : ' || left(btrim(p_reason), 300) || '.' else '' end
      || ' Vous pouvez envoyer un message pour vous expliquer et demander votre réintégration.',
    '/groups'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.handle_feed_report()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count integer;
  v_pro uuid;
  v_hidden boolean := false;
begin
  select count(distinct reporter_id) into v_count
  from public.feed_reports
  where target_type = new.target_type and target_id = new.target_id;

  if v_count >= 3 then
    if new.target_type = 'comment' then
      update public.feed_comments set is_hidden = true
      where id = new.target_id and is_hidden = false;
      v_hidden := found;
    elsif new.target_type = 'post' then
      update public.feed_content set is_published = false
      where id = new.target_id and source = 'member' and is_published = true;
      v_hidden := found;
    end if;
  end if;

  select id into v_pro from public.profiles where role = 'pro' order by created_at limit 1;

  if v_pro is not null and (v_count = 1 or v_hidden) then
    insert into public.scheduled_notifications
      (user_id, channel, type, title, body, link, payload, scheduled_for, sent_at)
    values (
      v_pro, 'in_app', 'report',
      case when v_hidden then 'Contenu masqué automatiquement' else 'Nouveau signalement' end,
      case when v_hidden
        then 'Un contenu a été signalé 3 fois et masqué en attendant votre décision.'
        else 'Un contenu du fil a été signalé par un membre.'
      end,
      '/pro/feed',
      jsonb_build_object('target_type', new.target_type, 'target_id', new.target_id),
      now(), now()
    );
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_feed_group()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pro uuid;
  v_pseudo text;
begin
  insert into public.feed_group_members (group_id, user_id, role, status)
  values (new.id, new.owner_id, 'owner', 'active')
  on conflict do nothing;

  insert into public.feed_group_members (group_id, user_id, role, status)
  select new.id, p.id, 'member', 'active'
  from public.profiles p
  where p.role = 'pro' and p.id <> new.owner_id
  on conflict do nothing;

  select id into v_pro from public.profiles where role = 'pro' order by created_at limit 1;

  if v_pro is not null and v_pro <> new.owner_id then
    select pseudo into v_pseudo from public.community_profiles where user_id = new.owner_id;

    insert into public.scheduled_notifications
      (user_id, channel, type, title, body, link, payload, scheduled_for, sent_at)
    values (
      v_pro, 'in_app', 'feed_group',
      'Nouveau groupe créé',
      coalesce(v_pseudo, 'Un membre') || ' a créé le groupe « ' || new.name || ' »',
      '/groups/' || new.id::text,
      jsonb_build_object('group_id', new.id),
      now(), now()
    );
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.invite_to_group(p_group uuid, p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_name text;
begin
  if not public.has_role(auth.uid(), 'pro'::public.app_role) then
    raise exception 'not_allowed';
  end if;

  select name into v_name from public.feed_groups where id = p_group;

  if v_name is null then
    raise exception 'group_not_found';
  end if;

  if public.has_role(p_user, 'pro'::public.app_role)
     or not public.can_participate_in_community(p_user) then
    raise exception 'not_eligible';
  end if;

  if public.is_banned_from_groups(p_user) or public.is_banned_from_group(p_user, p_group) then
    raise exception 'banned';
  end if;

  if public.is_group_member(p_user, p_group) then
    raise exception 'already_member';
  end if;

  insert into public.feed_group_members (group_id, user_id, role, status, invited_by)
  values (p_group, p_user, 'member', 'invited', auth.uid())
  on conflict (group_id, user_id) do update
    set status = 'invited', role = 'member', invited_by = auth.uid();

  perform public.notify_user(
    p_user, 'group_invite', 'Invitation à rejoindre un groupe',
    'Le coach vous invite à rejoindre le groupe « ' || v_name || ' ». Vous pouvez accepter ou refuser.',
    '/groups'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.join_group_by_code(p_code text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_group uuid;
  v_count integer;
begin
  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;

  if public.is_banned_from_groups(auth.uid()) then
    raise exception 'banned_from_group';
  end if;

  if not public.can_participate_in_community(auth.uid()) then
    raise exception 'not_allowed';
  end if;

  if not exists (select 1 from public.community_profiles where user_id = auth.uid()) then
    raise exception 'pseudo_required';
  end if;

  if not public.has_accepted_charter(auth.uid()) then
    raise exception 'charter_required';
  end if;

  select id into v_group from public.feed_groups
  where invite_code = p_code and invite_enabled = true;

  if v_group is null then
    raise exception 'invalid_code';
  end if;

  if public.is_banned_from_group(auth.uid(), v_group) then
    raise exception 'banned_from_group';
  end if;

  if not public.is_group_member(auth.uid(), v_group) then
    select count(*) into v_count from public.feed_group_members
    where group_id = v_group and status = 'active';
    if v_count >= 200 then
      raise exception 'group_full';
    end if;
  end if;

  insert into public.feed_group_members (group_id, user_id, role, status)
  values (v_group, auth.uid(), 'member', 'active')
  on conflict (group_id, user_id) do update set status = 'active'
  where public.feed_group_members.status = 'invited';

  return v_group;
end;
$function$

CREATE OR REPLACE FUNCTION public.respond_group_invitation(p_group uuid, p_accept boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_inviter uuid;
  v_name text;
  v_pseudo text;
  v_target uuid;
begin
  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;

  select invited_by into v_inviter
  from public.feed_group_members
  where group_id = p_group and user_id = auth.uid() and status = 'invited';

  if not found then
    raise exception 'no_invitation';
  end if;

  select name into v_name from public.feed_groups where id = p_group;
  select pseudo into v_pseudo from public.community_profiles where user_id = auth.uid();

  if p_accept then
    if not public.can_participate_in_community(auth.uid()) then
      raise exception 'not_allowed';
    end if;

    if v_pseudo is null then
      raise exception 'pseudo_required';
    end if;

    if not public.has_accepted_charter(auth.uid()) then
      raise exception 'charter_required';
    end if;

    if public.is_banned_from_groups(auth.uid()) or public.is_banned_from_group(auth.uid(), p_group) then
      raise exception 'banned';
    end if;

    update public.feed_group_members
    set status = 'active'
    where group_id = p_group and user_id = auth.uid();
  else
    delete from public.feed_group_members
    where group_id = p_group and user_id = auth.uid() and status = 'invited';
  end if;

  v_target := v_inviter;
  if v_target is null then
    select id into v_target from public.profiles where role = 'pro' order by created_at limit 1;
  end if;

  if v_target is not null and v_target <> auth.uid() then
    perform public.notify_user(
      v_target, 'group_invite',
      case when p_accept then 'Invitation acceptée' else 'Invitation refusée' end,
      coalesce(v_pseudo, 'Un membre')
        || case when p_accept then ' a accepté' else ' a refusé' end
        || ' votre invitation au groupe « ' || coalesce(v_name, '') || ' ».',
      '/groups/' || p_group::text
    );
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_appeal(p_group uuid, p_message text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_ban_created timestamptz;
  v_banned_by uuid;
  v_owner uuid;
  v_name text;
  v_pseudo text;
  v_pro uuid;
  v_id uuid;
  v_by_pro boolean;
begin
  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;

  if p_group is null then
    select created_at into v_ban_created from public.community_bans where user_id = auth.uid();
    v_by_pro := true;
  else
    select created_at, banned_by into v_ban_created, v_banned_by
    from public.feed_group_bans
    where group_id = p_group and user_id = auth.uid();
    v_by_pro := coalesce(public.has_role(v_banned_by, 'pro'::public.app_role), false);
  end if;

  if v_ban_created is null then
    raise exception 'not_banned';
  end if;

  if exists (
    select 1 from public.community_appeals a
    where a.user_id = auth.uid()
      and a.group_id is not distinct from p_group
      and a.created_at >= v_ban_created
  ) then
    raise exception 'already_sent';
  end if;

  insert into public.community_appeals (user_id, group_id, message)
  values (auth.uid(), p_group, btrim(p_message))
  returning id into v_id;

  select id into v_pro from public.profiles where role = 'pro' order by created_at limit 1;
  select pseudo into v_pseudo from public.community_profiles where user_id = auth.uid();

  if p_group is not null then
    select name, owner_id into v_name, v_owner from public.feed_groups where id = p_group;

    if v_owner is not null and v_owner is distinct from v_pro and not v_by_pro then
      perform public.notify_user(
        v_owner, 'appeal', 'Demande de réintégration',
        coalesce(v_pseudo, 'Un membre') || ' demande à être réintégré(e) dans le groupe « ' || coalesce(v_name, '') || ' ».',
        '/groups/' || p_group::text
      );
    end if;
  end if;

  if v_pro is not null and v_pro <> auth.uid() then
    perform public.notify_user(
      v_pro, 'appeal', 'Demande de réintégration',
      coalesce(v_pseudo, 'Un membre') || ' demande à être réintégré(e)'
        || case when p_group is null then ' dans la communauté.' else ' dans le groupe « ' || coalesce(v_name, '') || ' ».' end,
      case when p_group is null then '/groups' else '/groups/' || p_group::text end
    );
  end if;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.take_over_group(p_group uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_old uuid;
  v_name text;
begin
  if not public.has_role(auth.uid(), 'pro'::public.app_role) then
    raise exception 'not_allowed';
  end if;

  select owner_id, name into v_old, v_name from public.feed_groups where id = p_group;

  if v_old is null then
    raise exception 'group_not_found';
  end if;

  if v_old = auth.uid() then
    raise exception 'already_owner';
  end if;

  update public.feed_groups set owner_id = auth.uid() where id = p_group;

  insert into public.feed_group_members (group_id, user_id, role, status)
  values (p_group, auth.uid(), 'owner', 'active')
  on conflict (group_id, user_id) do update set role = 'owner', status = 'active';

  insert into public.feed_group_bans (group_id, user_id, reason, banned_by)
  values (p_group, v_old, left(p_reason, 300), auth.uid())
  on conflict (group_id, user_id) do update
    set reason = excluded.reason, banned_by = excluded.banned_by, created_at = now();

  update public.feed_group_members
  set status = 'banned', role = 'member'
  where group_id = p_group and user_id = v_old;

  perform public.notify_user(
    v_old, 'moderation', 'Vous avez été banni(e) d''un groupe',
    'Vous avez été banni(e) du groupe « ' || coalesce(v_name, '') || ' » car une règle de la charte de respect n''a pas été respectée. Le coach en est devenu le propriétaire.'
      || case when coalesce(btrim(p_reason), '') <> '' then ' Motif : ' || left(btrim(p_reason), 300) || '.' else '' end
      || ' Vous pouvez envoyer un message au coach pour vous expliquer et demander votre réintégration.',
    '/groups'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.unban_community_member(p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.has_role(auth.uid(), 'pro'::public.app_role) then
    raise exception 'not_allowed';
  end if;

  delete from public.community_bans where user_id = p_user;

  update public.community_appeals
  set status = 'accepted', handled_by = auth.uid(), handled_at = now()
  where user_id = p_user and group_id is null and status = 'pending';

  if public.can_participate_in_community(p_user) then
    update public.feed_group_members m
    set status = 'active'
    where m.user_id = p_user
      and m.status = 'banned'
      and not exists (
        select 1 from public.feed_group_bans b
        where b.group_id = m.group_id and b.user_id = m.user_id
      );
  end if;

  perform public.notify_user(
    p_user, 'moderation', 'Votre accès a été rétabli',
    'Votre bannissement a été levé. Vous retrouvez vos groupes et pouvez de nouveau participer à la communauté.',
    '/groups'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.unban_group_member(p_group uuid, p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_name text;
begin
  if not (public.is_group_owner(auth.uid(), p_group) or public.has_role(auth.uid(), 'pro'::public.app_role)) then
    raise exception 'not_allowed';
  end if;

  delete from public.feed_group_bans
  where group_id = p_group and user_id = p_user;

  update public.community_appeals
  set status = 'accepted', handled_by = auth.uid(), handled_at = now()
  where user_id = p_user and group_id = p_group and status = 'pending';

  if not public.is_banned_from_groups(p_user)
     and public.can_participate_in_community(p_user) then
    insert into public.feed_group_members (group_id, user_id, role, status)
    values (p_group, p_user, 'member', 'active')
    on conflict (group_id, user_id) do update set status = 'active';

    select name into v_name from public.feed_groups where id = p_group;

    perform public.notify_user(
      p_user, 'moderation', 'Vous avez été réintégré(e)',
      'Votre bannissement du groupe « ' || coalesce(v_name, '') || ' » a été levé. Vous faites de nouveau partie du groupe.',
      '/groups/' || p_group::text
    );
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.subscriber_access_state(p_user uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_role public.app_role;
  v_billing public.subscriber_billing%rowtype;
begin
  select role into v_role from public.profiles where id = p_user;
  if v_role is null then return 'unrestricted'; end if;
  if not public.billing_enabled() then return 'unrestricted'; end if;
  if v_role <> 'subscriber'::public.app_role then return 'unrestricted'; end if;
  select * into v_billing from public.subscriber_billing where user_id = p_user;
  if not found then return 'suspended'; end if;
  if v_billing.managed_by_pro then return 'managed'; end if;
  return case v_billing.status
    when 'active' then 'active'
    when 'trialing' then 'trial'
    when 'past_due' then 'past_due'
    else 'suspended'
  end;
end;
$function$
